ax1.plot(factors_x, ev, 'o-', color='#4f46e5', linewidth=2, markersize=6, label='Eigenvalues')
ax1.axhline(y=1.0, color='#f59e0b', linestyle='--', linewidth=1.8, label='Kaiser Criterion (λ = 1.0)')
